mapper.select:
SELECT a.id, a.user_id, a.job_id, a.company_id, a.resume_id, a.status, a.hr_remark, a.interview_time, a.interview_address, a.interview_contact, a.interview_contact_phone, a.interview_result, a.create_time, a.update_time, j.title AS job_name, c.company_name, c.logo AS company_logo, r.title AS resume_title FROM t_application a LEFT JOIN t_job j ON j.id = a.job_id LEFT JOIN t_company c ON c.id = a.company_id LEFT JOIN t_resume r ON r.id = a.resume_id
AND a.user_id = #{userId}
AND a.company_id = #{companyId}
AND a.status = #{status}
ORDER BY a.create_time DESC
